In `script.js`:

```javascript
const form = document.getElementById("marks-form");
const resultDiv = document.getElementById("result");

form.addEventListener("submit", function(e) {
    e.preventDefault(); // stop page reload

    const name = document.getElementById("student-name").value.trim();
    const markInputs = document.querySelectorAll(".subject-marks");

    // Collect all marks into an array
    const marks = [];
    let valid = true;

    markInputs.forEach(input => {
        const value = Number(input.value);
        if (value < 0 || value > 100 || input.value === "") {
            valid = false;
            input.classList.add("is-invalid");
        } else {
            input.classList.remove("is-invalid");
            marks.push(value);
        }
    });

    if (!valid || !name) {
        resultDiv.innerHTML = `<div class="alert alert-danger">Please fill all fields correctly (marks: 0-100)</div>`;
        return;
    }

    // Calculate
    const total = marks.reduce((sum, m) => sum + m, 0);
    const percentage = (total / (marks.length * 100)) * 100;
    const grade = getGrade(percentage);
    const status = percentage >= 33 ? "PASS" : "FAIL";

    // Display result
    displayResult(name, marks, total, percentage, grade, status);
});
```

Save and try submitting the form — it should prevent page reload.

Add these functions to `script.js`:

```javascript
function getGrade(percentage) {
    if (percentage >= 90) return { grade: "A+", color: "success" };
    if (percentage >= 75) return { grade: "A", color: "success" };
    if (percentage >= 60) return { grade: "B", color: "primary" };
    if (percentage >= 45) return { grade: "C", color: "warning" };
    if (percentage >= 33) return { grade: "D", color: "warning" };
    return { grade: "F", color: "danger" };
}

function displayResult(name, marks, total, percentage, gradeInfo, status) {
    const subjects = ["Hindi", "English", "Maths", "Science", "Computer"];

    let marksRows = "";
    subjects.forEach((sub, i) => {
        const badge = marks[i] >= 33 ? "bg-success" : "bg-danger";
        marksRows += `<tr>
            <td>${sub}</td>
            <td>${marks[i]}</td>
            <td><span class="badge ${badge}">${marks[i] >= 33 ? "Pass" : "Fail"}</span></td>
        </tr>`;
    });

    resultDiv.innerHTML = `
        <div class="card shadow-sm">
            <div class="card-body">
                <h4 class="card-title">${name}'s Result</h4>
                <table class="table table-striped">
                    <thead><tr><th>Subject</th><th>Marks</th><th>Status</th></tr></thead>
                    <tbody>${marksRows}</tbody>
                </table>
                <hr>
                <p><strong>Total:</strong> ${total} / ${marks.length * 100}</p>
                <p><strong>Percentage:</strong> ${percentage.toFixed(1)}%</p>
                <p><strong>Grade:</strong> <span class="badge bg-${gradeInfo.color} fs-6">${gradeInfo.grade}</span></p>
                <p><strong>Status:</strong> <span class="badge bg-${status === "PASS" ? "success" : "danger"} fs-6">${status}</span></p>
            </div>
        </div>
    `;
}
```

Test:
- Enter marks → click Calculate → see result card
- Try marks below 33 → subject should show "Fail" badge
- Try all marks above 90 → should show "A+" grade

